// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(bool useStolen, address baseToken, address nft, uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool payRoyalties, bytes32 salt) public {
        feeRate = uint16(feeRate % 6000);

        bool ok;
        try c.initialize(
            baseToken,
            nft,
            vBase,
            vNft,
            changeFee,
            feeRate,
            merkleRoot,
            useStolen,
            payRoyalties
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        vm.assume(ok);

        assertTrue(c.useStolenNftOracle() == useStolen);
    }
}
